import "./gym-disable-stats.css";
import { ttStorage } from "@common/utils/context";
import { filters, settings } from "@common/utils/data/database";
import { elementBuilder, findAllElements, isElement } from "@common/utils/functions/dom";
import { CUSTOM_LISTENERS, EVENT_CHANNELS } from "@common/utils/functions/listeners";
import { requireElement } from "@common/utils/functions/requires";
import { getPageStatus } from "@common/utils/functions/torn";
import { sleep } from "@common/utils/functions/utilities";
import { Feature } from "@features/feature";

function initialiseListeners() {
	CUSTOM_LISTENERS[EVENT_CHANNELS.GYM_LOAD].push(async () => {
		if (!settings.pages.gym.disableStats) return;

		await showCheckboxes();
	});

	const gymTrainObserver = new MutationObserver((mutations) => {
		if (!settings.pages.gym.disableStats) return;

		for (const mutation of mutations) {
			const target = mutation.target as Element;
			const checkbox = target.querySelector<HTMLInputElement>(".tt-stat-checkbox");
			if (!checkbox) continue;

			const classList = target.classList;
			if (!classList.contains("tt-modified")) classList.add("tt-modified");
			if (classList.contains("tt-gym-locked") !== checkbox.checked) classList.toggle("tt-gym-locked");
		}
	});

	requireElement("#gymroot ul[class*='properties_']").then((properties) => {
		gymTrainObserver.observe(properties, { attributes: true, subtree: true });
	});

	requireElement("#gymroot [class*='gym__']").then((gymRoot) => {
		new MutationObserver(async (mutations) => {
			if (!settings.pages.gym.disableStats) return;

			if (
				mutations.some((mutation) =>
					Array.from(mutation.addedNodes).some((node) => isElement(node) && node.className?.includes?.("gymContentWrapper__")),
				)
			) {
				void showCheckboxes();

				requireElement("#gymroot ul[class*='properties_']").then((properties) => {
					gymTrainObserver.observe(properties, { attributes: true, subtree: true });
				});
			}
		}).observe(gymRoot, { childList: true, subtree: true });
	});
}

async function showCheckboxes() {
	await sleep(10);

	const properties = (await requireElement("#gymroot ul[class*='properties___'] [class*='strength___']")).closest("#gymroot ul[class*='properties___']");

	for (const stat of findAllElements(":scope > li:not([class*='locked___']):not(.tt-modified)", properties)) {
		stat.classList.add("tt-modified");
		stat.appendChild(
			elementBuilder({
				type: "input",
				class: "tt-stat-checkbox",
				attributes: { type: "checkbox" },
				events: {
					click() {
						toggleStat(stat);
					},
				},
			}),
		);

		const name = ["strength", "speed", "dexterity", "defense"].find((s) => stat.className.includes(s));
		if (!name) continue;

		if (filters.gym[name]) toggleStat(stat, false);
	}

	function toggleStat(stat: Element, save = true) {
		const checkbox = stat.querySelector<HTMLInputElement>(".tt-stat-checkbox");
		const button = stat.querySelector<HTMLButtonElement>(".torn-btn");

		const isLocked = stat.classList.toggle("tt-gym-locked");

		if (isLocked) button.disabled = true;
		else button.removeAttribute("disabled");
		checkbox.checked = isLocked;

		if (save) {
			const name = ["strength", "speed", "dexterity", "defense"].find((s) => stat.className.includes(s));

			if (name) ttStorage.change({ filters: { gym: { [name]: isLocked } } });
		}
	}
}

function dispose() {
	for (const checkbox of findAllElements(".tt-stat-checkbox")) checkbox.remove();
	for (const stat of findAllElements(".tt-gym-locked, #gymroot ul[class*='properties___'] > li.tt-modified"))
		stat.classList.remove(".tt-gym-locked", "tt-modified");
}

export default class GymDisableStatsFeature extends Feature {
	constructor() {
		super("Disable Stats", "gym");
	}

	precondition() {
		return getPageStatus().access;
	}

	isEnabled() {
		return settings.pages.gym.disableStats;
	}

	initialise() {
		initialiseListeners();
	}

	async execute() {
		await showCheckboxes();
	}

	cleanup() {
		dispose();
	}

	storageKeys() {
		return ["settings.pages.gym.disableStats", "filters.gym"];
	}
}
