import "./faction-quick-items.css";
import { isInternalFaction } from "@common/pages/factions-page";
import type { TornInternalUseItem } from "@common/pages/item-page";
import { FEATURE_MANAGER, ITEM_RESOLVER, ttStorage } from "@common/utils/context";
import { quick, settings } from "@common/utils/data/database";
import type { QuickFactionItem } from "@common/utils/data/default-database";
import { fetchData } from "@common/utils/functions/api-fetcher";
import { createContainer, findContainer, removeContainer } from "@common/utils/functions/containers";
import { elementBuilder, findAllElements, findParent, isElement, mobile, tablet } from "@common/utils/functions/dom";
import { formatTime } from "@common/utils/functions/formatting";
import { CUSTOM_LISTENERS, EVENT_CHANNELS } from "@common/utils/functions/listeners";
import { requireElement } from "@common/utils/functions/requires";
import { getItemEnergy, getPageStatus, getUserEnergy } from "@common/utils/functions/torn";
import { PHFillPlus, PHX } from "@common/utils/icons/phosphor-icons";
import { Feature } from "@features/feature";

let movingElement: Element | undefined;
let isEditing = false;

function addListener() {
	document.addEventListener(
		"click",
		(event) => {
			if (isElement(event.target) && event.target.classList.contains("close-act")) {
				const responseWrap = findParent(event.target, { class: "response-wrap" });

				if (responseWrap) responseWrap.style.display = "none";
			}
		},
		{ passive: true },
	);
	setInterval(() => {
		for (const timer of findAllElements(".counter-wrap.tt-modified")) {
			let secondsLeft: number;
			if ("secondsLeft" in timer.dataset) secondsLeft = parseInt(timer.dataset.secondsLeft);
			else secondsLeft = parseInt(timer.dataset.time);
			secondsLeft--;
			if (secondsLeft < 0) secondsLeft = 0;

			timer.textContent = formatTime({ seconds: secondsLeft }, { type: "timer", daysToHours: true });

			timer.dataset.secondsLeft = `${secondsLeft}`;
		}
	}, 1000);

	CUSTOM_LISTENERS[EVENT_CHANNELS.FACTION_ARMORY_TAB].push(async ({ section }) => {
		if (!FEATURE_MANAGER.isEnabled(FactionQuickItemsFeature)) return;

		if (["medical", "drugs", "boosters", "points", "donate", "consumables", "loot", "utilities"].includes(section)) {
			await showQuickItems(section);
			setupQuickDragListeners();
			setupOverlayItems(document);
			attachEditListeners(isEditing);
		} else hideQuickItems();
	});
}

async function showQuickItems(section: string) {
	if (!section) return;

	const presentFilter = findContainer("Faction Quick Items");
	if (presentFilter) {
		presentFilter.classList.remove("tt-hidden");
		return;
	}

	const { content, options } = createContainer("Faction Quick Items", {
		class: "mt10",
		nextElement: document.querySelector("#faction-armoury > hr"),
		allowDragging: true,
		compact: true,
	});
	content.appendChild(elementBuilder({ type: "div", class: "inner-content" }));
	content.appendChild(elementBuilder({ type: "div", class: "response-wrap" }));
	options.appendChild(
		elementBuilder({
			type: "div",
			class: "option",
			id: "edit-items-button",
			children: [PHFillPlus(), "Edit"],
			events: {
				click: (event) => {
					event.stopPropagation();

					const enabled = options.querySelector("#edit-items-button").classList.toggle("tt-overlay-item");
					isEditing = enabled;

					const content = findContainer("Faction Quick Items", { selector: ":scope > main" });
					for (const quick of findAllElements(".item", content)) {
						if (enabled) {
							quick.classList.add("tt-overlay-item");
							quick.classList.add("removable");
						} else {
							quick.classList.remove("tt-overlay-item");
							quick.classList.remove("removable");
						}
					}

					for (const category of findAllElements("#faction-armoury-tabs .torn-tabs > li")) {
						if (
							!["Medical", "Drugs", "Boosters", "Points", "Consumables", "Loot", "Utilities"].includes(
								category.querySelector("a.ui-tabs-anchor").textContent.trim(),
							)
						)
							continue;

						if (enabled) category.classList.add("tt-overlay-item");
						else category.classList.remove("tt-overlay-item");
					}
					for (const item of findAllElements(
						".armoury-medical-wrap, .armoury-drugs-wrap, .armoury-boosters-wrap, .armoury-points-wrap, .armoury-consumables-wrap, .armoury-temporary-wrap",
					)) {
						if (enabled) item.classList.add("tt-overlay-item-notbroken");
						else item.classList.remove("tt-overlay-item-notbroken");
					}

					if (enabled) document.querySelector(".tt-overlay").classList.remove("tt-hidden");
					else document.querySelector(".tt-overlay").classList.add("tt-hidden");

					attachEditListeners(enabled);
				},
			},
		}),
	);

	for (const quickItem of quick.factionItems) {
		addQuickItem(quickItem, false);
	}

	requireElement(".armoury-tabs[aria-expanded=true] .name, .armoury-donate-wrap[aria-expanded=true]").then(setupQuickDragListeners);
}

function setupQuickDragListeners() {
	const enableDrag = !mobile && !tablet;
	const tab = document.querySelector("#faction-armoury-tabs .armoury-tabs[aria-expanded='true']");

	if (tab.id === "tab=armoury&sub=points") {
		for (const item of findAllElements(".give[data-role]", tab)) {
			const type = item.textContent.trim().split(" ")[1].toLowerCase();

			item.dataset.type = "tt-points";
			if (enableDrag) {
				item.setAttribute("draggable", "true");
				item.addEventListener("dragstart", onDragStart);
				item.addEventListener("dragend", onDragEnd);
			}

			item.appendChild(
				elementBuilder({
					type: "div",
					class: "img-wrap tt-lazy-magic",
					dataset: { itemid: `points-${type}` },
					style: { display: "none" },
				}),
			);
		}
	} else {
		for (const item of findAllElements(".item-list > li", tab)) {
			const imgWrap = item.querySelector<HTMLElement>(".img-wrap");

			if (!allowQuickItem(parseInt(imgWrap.dataset.itemid), item.querySelector(".type")?.textContent)) continue;

			if (enableDrag) {
				item.setAttribute("draggable", "true");
				item.addEventListener("dragstart", onDragStart);
				item.addEventListener("dragend", onDragEnd);
			}
		}
	}

	function onDragStart(event: DragEvent) {
		event.dataTransfer.setData("text/plain", null);

		setTimeout(() => {
			document.querySelector("#factionQuickItems > main").classList.add("drag-progress");
			if (document.querySelector("#factionQuickItems .temp.item") || !isElement(event.target)) return;

			let target = event.target;
			if (!target.hasAttribute("draggable")) {
				const actualTarget = target.closest("[draggable]");

				if (actualTarget) target = actualTarget;
			}

			const _id = target.querySelector<HTMLElement>(".img-wrap").dataset.itemid;
			const id = Number.isNaN(parseInt(_id)) ? _id : parseInt(_id);

			addQuickItem({ id }, true);
		}, 10);
	}

	async function onDragEnd() {
		if (document.querySelector("#factionQuickItems .temp.item")) {
			document.querySelector("#factionQuickItems .temp.item").remove();
		}

		document.querySelector("#factionQuickItems > main").classList.remove("drag-progress");

		await saveQuickItems();
	}
}

function addQuickItem(data: { id: string | number }, temporary = false) {
	const content = findContainer("Faction Quick Items", { selector: ":scope > main" });
	const innerContent = content.querySelector(".inner-content");
	const responseWrap = content.querySelector<HTMLElement>(".response-wrap");

	const { id } = data;

	if (innerContent.querySelector(`.item[data-id='${id}']`)) return innerContent.querySelector(`.item[data-id='${id}']`);
	if (!allowQuickItem(id, typeof id === "number" ? ITEM_RESOLVER.getStaticItem(id)?.type : null)) return null;

	const itemWrap = elementBuilder({
		type: "div",
		class: temporary ? "temp item" : "item",
		dataset: data,
		events: {
			click: async () => {
				if (itemWrap.classList.contains("removable")) {
					itemWrap.remove();
					itemWrap.dispatchEvent(new Event("mouseout"));
					closeIcon.dispatchEvent(new Event("mouseout"));
					await saveQuickItems();
					return;
				}

				if (settings.pages.items.energyWarning && typeof id === "number" && ["Drug", "Energy Drink"].includes(ITEM_RESOLVER.getStaticItem(id)?.type)) {
					const received = getItemEnergy(id);
					if (received) {
						const [current, max] = getUserEnergy();
						if (current > max && received + current > 1000) {
							if (!confirm("Are you sure to use this item ? It will get you to more than 1000E.")) return;
						}
					}
				}

				const body = new URLSearchParams();

				if (id === "points-energy" || id === "points-nerve") {
					body.set("step", "armouryRefillEnergy");
					if (id === "points-energy") body.set("step", "armouryRefillEnergy");
					else if (id === "points-nerve") body.set("step", "armouryRefillNerve");

					fetchData("torn_direct", { action: "factions.php", method: "POST", body }).then((result) => {
						responseWrap.style.display = "block";
						responseWrap.innerHTML = "";

						responseWrap.appendChild(elementBuilder({ type: "span", class: `t-${result.success ? "green" : "red"} bold`, html: result.message }));
						responseWrap.appendChild(
							elementBuilder({
								type: "div",
								style: { display: "block" },
								children: [elementBuilder({ type: "a", href: "#", class: "close-act t-blue bold c-pointer", text: "Okay" })],
							}),
						);
					});
				} else {
					Object.entries({ step: "useItem", fac: "1", itemID: id }).forEach(([key, value]) => body.set(key, value.toString()));

					fetchData<TornInternalUseItem>("torn_direct", { action: "item.php", method: "POST", body }).then(async (result) => {
						if (typeof result !== "object") return;

						const links = [elementBuilder({ type: "a", href: "#", class: "close-act t-blue h", text: "Close" })];
						if ("links" in result) {
							for (const link of result.links) {
								links.push(
									elementBuilder({
										type: "a",
										class: `t-blue h m-left10 ${link.class}`,
										href: link.url,
										text: link.title,
										attributes: Object.fromEntries(
											link.attr
												.split(" ")
												.filter((x) => !!x)
												.map((x) => x.split("=")),
										),
									}),
								);
							}
						}

						responseWrap.style.display = "block";
						responseWrap.innerHTML = "";
						responseWrap.appendChild(
							elementBuilder({
								type: "div",
								class: "armoury-tabs",
								children: [
									elementBuilder({
										type: "ul",
										class: "item-list",
										children: [
											elementBuilder({
												type: "li",
												class: "item-use-act",
												children: [
													elementBuilder({
														type: "div",
														class: "name",
														children: [elementBuilder({ type: "span", class: "qty", text: "10000" })],
													}),
													elementBuilder({
														type: "div",
														class: "use-cont action-cont",
														children: [
															elementBuilder({
																type: "div",
																class: "use-wrap",
																children: [
																	elementBuilder({
																		type: "form",
																		dataset: { action: "useItem" },
																		attributes: { method: "post" },
																		children: [
																			elementBuilder({ type: "p", html: result.text }),
																			elementBuilder({ type: "p", children: links }),
																			elementBuilder({ type: "div", class: "clear" }),
																		],
																	}),
																],
																style: { display: "block" },
															}),
														],
														dataset: { itemid: id },
													}),
													elementBuilder({ type: "div", class: "clear" }),
												],
											}),
										],
									}),
								],
							}),
						);

						for (const count of findAllElements(".counter-wrap", responseWrap)) {
							count.classList.add("tt-modified");
							count.textContent = formatTime({ seconds: parseInt(count.dataset.time) }, { type: "timer", daysToHours: true });
						}
					});
				}
			},
			dragstart(event) {
				event.dataTransfer.effectAllowed = "move";
				event.dataTransfer.setDragImage(event.currentTarget as Element, 0, 0);

				movingElement = event.currentTarget as Element;
			},
			async dragend() {
				movingElement.classList.remove("temp");
				movingElement = undefined;

				await saveQuickItems();
			},
			dragover(event) {
				event.preventDefault();
			},
			dragenter(event) {
				if (movingElement !== event.currentTarget) {
					const children = Array.from(innerContent.children);

					const currentTarget = event.currentTarget as Element;
					if (children.indexOf(movingElement) > children.indexOf(currentTarget)) innerContent.insertBefore(movingElement, currentTarget);
					else if (currentTarget.nextElementSibling) {
						innerContent.insertBefore(movingElement, currentTarget.nextElementSibling);
					} else {
						innerContent.appendChild(movingElement);
					}
					movingElement.classList.add("temp");
				}
			},
		},
		attributes: {
			draggable: true,
		},
	});
	switch (id) {
		case "points-energy":
			itemWrap.appendChild(
				elementBuilder({
					type: "div",
					class: "pic icon-refill",
					children: [elementBuilder({ type: "i", class: "currency-points" })],
				}),
			);
			itemWrap.setAttribute("title", "Energy Refill");
			itemWrap.appendChild(elementBuilder({ type: "div", class: "text", text: "Energy Refill" }));
			break;
		case "points-nerve":
			itemWrap.appendChild(
				elementBuilder({
					type: "div",
					class: "pic icon-refill",
					children: [elementBuilder({ type: "i", class: "currency-points" })],
				}),
			);
			itemWrap.setAttribute("title", "Nerve Refill");
			itemWrap.appendChild(elementBuilder({ type: "div", class: "text", text: "Nerve Refill" }));
			break;
		default: {
			itemWrap.appendChild(elementBuilder({ type: "div", class: "pic", attributes: { style: `background-image: url(/images/items/${id}/medium.png)` } }));

			const item = ITEM_RESOLVER.getStaticItem(parseInt(String(id)));
			if (item) {
				itemWrap.setAttribute("title", item.name);
				itemWrap.appendChild(elementBuilder({ type: "div", class: "text", text: item.name }));
			} else {
				itemWrap.appendChild(elementBuilder({ type: "div", class: "text", text: id }));
			}
			break;
		}
	}

	const closeIcon = elementBuilder({
		type: "svg",
		class: "tt-close-icon",
		children: [PHX()],
		attributes: { title: "Remove quick access." },
		events: {
			click: async (event) => {
				event.stopPropagation();
				itemWrap.dispatchEvent(new Event("mouseout"));
				closeIcon.dispatchEvent(new Event("mouseout"));
				itemWrap.remove();

				await saveQuickItems();
			},
		},
	});
	itemWrap.appendChild(closeIcon);
	innerContent.appendChild(itemWrap);
	return itemWrap;
}

async function saveQuickItems() {
	const content = findContainer("Faction Quick Items", { selector: ":scope > main" });

	await ttStorage.change({
		quick: {
			factionItems: findAllElements(".item", content)
				.map((x) => x.dataset.id)
				.map((x) => (Number.isNaN(parseInt(x)) ? (x as QuickFactionItem["id"]) : parseInt(x)))
				.map((x) => ({ id: x })),
		},
	});
}

function allowQuickItem(id: number | string, category: string | null) {
	return ["Medical", "Drug", "Energy Drink", "Alcohol", "Candy", "Booster"].includes(category) || id === "points-energy" || id === "points-nerve";
}

function hideQuickItems() {
	findContainer("Faction Quick Items")?.classList?.add("tt-hidden");
}

function attachEditListeners(enabled: boolean) {
	if (enabled) {
		for (const item of findAllElements(".armoury-tabs .item-list > li")) {
			const imgWrap = item.querySelector<HTMLElement>(".img-wrap");

			if (!allowQuickItem(imgWrap.dataset.itemid, item.querySelector(".type")?.textContent)) continue;

			item.addEventListener("click", onItemClickQuickEdit);
		}
		for (const refill of findAllElements("#armoury-points .give[data-role='give'], #armoury-points .give[data-role='refill']")) {
			refill.addEventListener("click", onItemClickQuickEdit);
		}
	} else {
		for (const item of findAllElements(".armoury-tabs .item-list > li")) {
			const imgWrap = item.querySelector<HTMLElement>(".img-wrap");

			if (!allowQuickItem(imgWrap.dataset.itemid, item.querySelector(".type")?.textContent)) continue;

			item.removeEventListener("click", onItemClickQuickEdit);
		}
		for (const refill of findAllElements("#armoury-points .give[data-role='give'], #armoury-points .give[data-role='refill']")) {
			refill.removeEventListener("click", onItemClickQuickEdit);
		}
	}
}

async function onItemClickQuickEdit(event: MouseEvent) {
	event.stopPropagation();
	event.preventDefault();

	const _target = event.target as HTMLElement;
	const target = _target.dataset.type === "tt-points" ? _target : findParent(_target, { tag: "LI" });
	const _id = target.querySelector<HTMLElement>(".img-wrap").dataset.itemid;
	const id = Number.isNaN(parseInt(_id)) ? _id : parseInt(_id);

	const item = addQuickItem({ id }, false);
	if (item) item.classList.add("tt-overlay-item", "removable");

	await saveQuickItems();
}

function setupOverlayItems(tab: Document | Element) {
	for (const item of findAllElements(".item-list > li", tab)) {
		const imgWrap = item.querySelector<HTMLElement>(".img-wrap");

		if (allowQuickItem(parseInt(imgWrap.dataset.itemid), item.querySelector(".type")?.textContent)) continue;

		item.classList.add("tt-overlay-ignore");
	}
}

export default class FactionQuickItemsFeature extends Feature {
	constructor() {
		super("Faction Quick Items", "faction");
	}

	precondition() {
		return isInternalFaction && getPageStatus().access;
	}

	isEnabled() {
		return settings.pages.faction.quickItems;
	}

	initialise() {
		addListener();
	}

	cleanup() {
		removeContainer("Faction Quick Items");
	}

	storageKeys() {
		return ["settings.pages.faction.quickItems"];
	}

	shouldLiveReload() {
		return true;
	}
}
