import "./company-specials.css";
import { FEATURE_MANAGER } from "@common/utils/context";
import { ttCache } from "@common/utils/data/cache";
import { settings, userdata } from "@common/utils/data/database";
import { hasAPIData } from "@common/utils/functions/api";
import { fetchData } from "@common/utils/functions/api-fetcher";
import { elementBuilder, findAllElements } from "@common/utils/functions/dom";
import { formatNumber } from "@common/utils/functions/formatting";
import { addXHRListener } from "@common/utils/functions/listeners";
import { requireElement } from "@common/utils/functions/requires";
import { getPageStatus } from "@common/utils/functions/torn";
import { TO_MILLIS } from "@common/utils/functions/utilities";
import { Feature } from "@features/feature";
import type { UserCompany, UserJob, UserJobResponse } from "tornapi-typescript";

const data: Record<number, any> = {};

function initialiseCompanySpecials() {
	addXHRListener(async ({ detail }) => {
		if (!FEATURE_MANAGER.isEnabled(CompanySpecialsFeature) || !("json" in detail)) return;

		const { page, json } = detail;

		if (page === "companies" && json) {
			if (json.result?.msg) {
				if (json.result.msg.money) showMuggableCash(json).catch((error) => console.error("Couldn't show the muggable cash.", error));
				if (json.result.msg.total) calculateSpies(json).catch((error) => console.error("Couldn't help with the spies.", error));
			}
		}
	});
}

async function showMuggableCash(json: any) {
	const api = hasAPIData() && settings.apiUsage.user.merits;

	let percentageMin = 5;
	let percentageMax = 10;

	if (api) {
		const masterfulLooting = userdata.merits.upgrades.find(({ id }) => id === 5)?.level ?? 0;
		const merits = 1 + masterfulLooting * 0.05;
		percentageMin *= merits;
		percentageMax *= merits;

		const id = json.result.user.userID;
		let jobResult: UserJob | UserCompany;
		if (ttCache.hasValue("user-job", id)) {
			jobResult = ttCache.get("user-job", id);
		} else {
			jobResult = (
				await fetchData<UserJobResponse>("tornv2", {
					section: "user",
					id,
					selections: ["job"],
					silent: true,
				})
			).job;

			ttCache.set({ [id]: jobResult }, TO_MILLIS.SECONDS * 30, "user-job").then(() => {});
		}

		if (jobResult && jobResult.type === "company" && jobResult.type_id === 5 && jobResult.rating >= 7) {
			percentageMin /= 4;
			percentageMax /= 4;
		}
	}

	const cash = parseInt(json.result.msg.money.replaceAll(",", ""));

	const jobInfo = await requireElement(".job-info");
	jobInfo.appendChild(
		elementBuilder({
			type: "li",
			text: `Potential mug${api ? "" : "*"}: ${formatNumber(cash * (percentageMin / 100), { currency: true })} - ${formatNumber(
				cash * (percentageMax / 100),
				{ currency: true },
			)}`,
		}),
	);
	if (!api) jobInfo.appendChild(elementBuilder({ type: "li", text: "* Might not be entirely accurate due to missing API information." }));
}

async function calculateSpies(json: any) {
	const user = parseInt(json.result.user.userID);

	const stats = ["strength", "speed", "dexterity", "defense", "total"];
	const result: Record<string, number> = {};
	const missing: string[] = [];
	const remembered: string[] = [];
	for (let [key, value] of Object.entries(json.result.msg)) {
		if (key === "defence") key = "defense";

		if (!stats.includes(key) || typeof value !== "string") continue;

		if (value === "N/A") {
			if (data[user] && data[user][key] !== -1) {
				value = data[user][key];
				remembered.push(key);
			} else {
				value = -1;
				missing.push(key);
			}
		} else {
			value = parseInt(value.replaceAll(",", ""));
		}

		result[key] = value as number;
	}

	await requireElement(".specials-confirm-cont ul.job-info > li");

	const specialContext = document.querySelector(".specials-confirm-cont");

	if (missing.length === 1) {
		const missingStat = missing[0];

		result[missingStat] = Object.entries(result)
			.filter(([stat]) => missingStat !== stat)
			.map(([stat, value]) => (stat === "total" || missingStat === "total" ? value : -value) as number)
			.reduce((a, b) => a + b, 0);

		const element = findAllElements("ul.job-info > li", specialContext).find((element) => element.textContent.toLowerCase().startsWith(missingStat));

		if (element) {
			element.classList.add("missing");
			element.textContent = `${element.textContent.split(" ")[0]} ${formatNumber(result[missingStat])}`;
		}
	}
	for (const stat of remembered) {
		const element = findAllElements("ul.job-info > li", specialContext).find((element) => element.textContent.toLowerCase().startsWith(stat));
		if (!element) continue;

		element.classList.add("remembered");
		element.textContent = `${element.textContent.split(" ")[0]} ${formatNumber(result[stat])}`;
	}
	data[user] = result;

	console.log("TT - Detected stat spy: ", result, { missing, remembered });

	if (settings.external.tornstats) {
		specialContext.classList.add("tt-modified");

		const backWrap = specialContext.querySelector(".back");

		if (backWrap) {
			const button = elementBuilder({
				type: "button",
				class: "external-service tt-btn",
				text: "Save to TornStats",
				events: {
					click() {
						const id = parseInt(json.result.user.userID);

						fetchData("tornstats", {
							section: "store/spy",
							method: "POST",
							params: {
								player_id: id,
								player_name: json.result.user.playername,
								player_level: parseInt(json.result.user.level),
								...data[user],
							},
							relay: true,
						})
							.then((response) => {
								const responseElement = specialContext.querySelector(".external-response");

								if (response.status) {
									if (responseElement) {
										responseElement.className = `external-response ${!response.status ? "error" : ""}`;
										responseElement.textContent = response.message;
									}
									button.setAttribute("disabled", "");
								} else {
									button.removeAttribute("disabled");
								}

								ttCache.remove("tornstats-spy", id);

								if (!responseElement) {
									specialContext.appendChild(
										elementBuilder({
											type: "div",
											class: "external-response-wrap",
											children: [
												elementBuilder({
													type: "span",
													class: `external-response ${!response.status ? "error" : ""}`,
													text: response.message,
												}),
											],
										}),
									);
								}
							})
							.catch((error) => {
								console.error("Couldn't store your spy to TornStats.", error);
								specialContext.appendChild(
									elementBuilder({
										type: "div",
										class: "external-response-wrap",
										children: [elementBuilder({ type: "span", class: "external-response error", text: "Something went wrong!" })],
									}),
								);
							});
					},
				},
			});

			backWrap.insertBefore(button, backWrap.firstElementChild);
		}
	}
}

export default class CompanySpecialsFeature extends Feature {
	constructor() {
		super("Company Specials", "companies");
	}

	precondition() {
		return getPageStatus().access;
	}

	isEnabled() {
		return settings.pages.companies.specials;
	}

	initialise() {
		initialiseCompanySpecials();
	}

	storageKeys() {
		return ["settings.pages.companies.specials"];
	}
}
